# binary_search.py
def binary_search(arr, target):
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

sorted_arr = sorted(map(int, input("Enter sorted list elements separated by space: ").split()))
target = int(input("Enter element to search: "))
print(f"Index of {target}: {binary_search(sorted_arr, target)}")

# bubble_sort.py
def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

nums = list(map(int, input("Enter numbers separated by space to sort: ").split()))
print(f"Sorted: {bubble_sort(nums)}")

# stack.py
class Stack:
    def __init__(self):
        self.items = []
    def push(self, item):
        self.items.append(item)
    def pop(self):
        return self.items.pop() if not self.is_empty() else None
    def peek(self):
        return self.items[-1] if not self.is_empty() else None
    def is_empty(self):
        return len(self.items) == 0

s = Stack()
s.push(1); s.push(2); s.push(3)
print("Popped:", s.pop())
print("Top:", s.peek())

# queue.py
from collections import deque

class Queue:
    def __init__(self):
        self.items = deque()
    def enqueue(self, item):
        self.items.append(item)
    def dequeue(self):
        return self.items.popleft() if not self.is_empty() else None
    def is_empty(self):
        return len(self.items) == 0

q = Queue()
q.enqueue('a'); q.enqueue('b'); q.enqueue('c')
print("Dequeued:", q.dequeue())
print("Next:", q.items[0] if not q.is_empty() else None)

